import React from "react";

import {
  Alert,
  Box,
  CircularProgress,
  Grid,
  IconButton,
  Stack,
  Tooltip,
  Typography,
} from "@mui/material";

import {
  RefreshRounded,
} from "@mui/icons-material";

import {
  useInferenceMonitoring,
} from "../hooks/useInferenceMonitoring";

import MonitoringSummary from "../components/MonitoringSummary";
import ResourceHealth from "../components/ResourceHealth";
import LatencyChart from "../components/LatencyChart";
import InferenceActivity from "../components/InferenceActivity";
import ResourceActivityTable from "../components/ResourceActivityTable";
import RecentErrors from "../components/RecentErrors";

const InferenceMonitoringPage = () => {
  const {
    summary,
    events,
    isLoading,
    isError,
    error,
    refetch,
  } = useInferenceMonitoring();

  /*
   * ------------------------------------------------------------
   * Loading
   * ------------------------------------------------------------
   */

  if (isLoading) {
    return (
      <Box
        sx={{
          minHeight: 500,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <CircularProgress />
      </Box>
    );
  }

  /*
   * ------------------------------------------------------------
   * Error
   * ------------------------------------------------------------
   */

  if (isError || !summary) {
    return (
      <Box
        sx={{
          p: {
            xs: 2,
            md: 3,
          },
        }}
      >
        <Alert severity="error">
          <Typography fontWeight={600}>
            Unable to load inference monitoring data.
          </Typography>

          {error instanceof Error && (
            <Typography
              variant="body2"
              sx={{ mt: 0.5 }}
            >
              {error.message}
            </Typography>
          )}
        </Alert>
      </Box>
    );
  }

  /*
   * ------------------------------------------------------------
   * Safe data references
   *
   * The backend may legitimately return empty arrays when no
   * inference has run since the API process started.
   * ------------------------------------------------------------
   */

  const runs = summary.runs ?? [];

  const resources =
    summary.resources ?? [];

  const monitoringEvents =
    events ?? [];

  return (
    <Box
      sx={{
        width: "100%",
        p: {
          xs: 2,
          sm: 2.5,
          md: 3,
        },
      }}
    >
      {/* ======================================================
          PAGE HEADER
          ====================================================== */}

      <Stack
        direction={{
          xs: "column",
          sm: "row",
        }}
        justifyContent="space-between"
        alignItems={{
          xs: "flex-start",
          sm: "center",
        }}
        spacing={2}
        sx={{
          mb: 3,
        }}
      >
        <Box>
          <Typography
            variant="h4"
            fontWeight={700}
          >
            Inference Monitoring
          </Typography>

          <Typography
            color="text.secondary"
            sx={{
              mt: 0.5,
              maxWidth: 800,
            }}
          >
            Operational visibility into inference
            executions, resource interactions and
            external service health.
          </Typography>
        </Box>

        <Tooltip
          title="Refresh monitoring data"
        >
          <IconButton
            onClick={() => void refetch()}
            sx={{
              border: 1,
              borderColor: "divider",
              borderRadius: 2,
            }}
          >
            <RefreshRounded />
          </IconButton>
        </Tooltip>
      </Stack>

      {/* ======================================================
          SUMMARY / KPIs
          ====================================================== */}

      <MonitoringSummary
        summary={summary}
      />

      {/* ======================================================
          LATENCY + RECENT ERRORS
          ====================================================== */}

      <Grid
        container
        spacing={2}
        sx={{
          mb: 3,
        }}
      >
        <Grid
          item
          xs={12}
          lg={7}
        >
          <LatencyChart
            runs={runs}
          />
        </Grid>

        <Grid
          item
          xs={12}
          lg={5}
        >
          <RecentErrors
            events={monitoringEvents}
          />
        </Grid>
      </Grid>

      {/* ======================================================
          RESOURCE HEALTH
          ====================================================== */}

      <Box
        sx={{
          mb: 3,
        }}
      >
        <ResourceHealth
          resources={resources}
        />
      </Box>

      {/* ======================================================
          INFERENCE ACTIVITY
          ====================================================== */}

      <Box
        sx={{
          mb: 3,
        }}
      >
        <InferenceActivity
          runs={runs}
        />
      </Box>

      {/* ======================================================
          RESOURCE ACTIVITY
          ====================================================== */}

      <Box
        sx={{
          mb: 3,
        }}
      >
        <ResourceActivityTable
          events={monitoringEvents}
        />
      </Box>

      {/* ======================================================
          FOOTER / MONITORING WINDOW
          ====================================================== */}

      <Box
        sx={{
          pt: 1,
          pb: 2,
        }}
      >
        <Typography
          variant="caption"
          color="text.secondary"
        >
          Monitoring data refreshes automatically
          every 30 seconds.
        </Typography>
      </Box>
    </Box>
  );
};

export default InferenceMonitoringPage;
